require "openssl"

# Test certificates and signed files (CAdES .p7m and PAdES PDF) built on the fly with OpenSSL.
module SigningHelpers
  QC_COMPLIANCE = "0.4.0.1862.1.1"
  QC_SSCD = "0.4.0.1862.1.4"

  # A minimal unsigned PDF, standing in for the one generated by the app
  def sample_pdf
    <<~PDF.b
      %PDF-1.4
      1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
      2 0 obj << /Type /Pages /Kids [] /Count 0 >> endobj
      trailer << /Root 1 0 R >>
      %%EOF
    PDF
  end

  def signing_ca
    @signing_ca ||= begin
      key = OpenSSL::PKey::RSA.new(2048)
      cert = build_cert(subject: "/C=IT/O=Prova QTSP S.p.A./CN=Prova Qualified CA", key: key, issuer_key: key)
      { key: key, cert: cert }
    end
  end

  # Signer certificate issued by the test CA, qualified by default
  def signer_certificate(qualified: true, non_repudiation: true, not_before: 1.year.ago, not_after: 2.years.from_now)
    key = OpenSSL::PKey::RSA.new(2048)
    cert = build_cert(
      subject: "/C=IT/GN=Mario/SN=Rossi/CN=ROSSI MARIO/serialNumber=TINIT-RSSMRA80A01H501Z",
      key: key, issuer_key: signing_ca[:key], issuer: signing_ca[:cert], not_before: not_before, not_after: not_after
    ) do |c, ef|
      c.add_extension(ef.create_extension("keyUsage", non_repudiation ? "nonRepudiation" : "digitalSignature", true))
      if qualified
        qc = OpenSSL::ASN1::Sequence([ OpenSSL::ASN1::Sequence([ OpenSSL::ASN1::ObjectId(QC_COMPLIANCE) ]),
                                       OpenSSL::ASN1::Sequence([ OpenSSL::ASN1::ObjectId(QC_SSCD) ]) ])
        c.add_extension(OpenSSL::X509::Extension.new("1.3.6.1.5.5.7.1.3", qc.to_der))
      end
    end
    { key: key, cert: cert }
  end

  def cades(content, signer: signer_certificate, detached: false, base64: false)
    flags = OpenSSL::PKCS7::BINARY
    flags |= OpenSSL::PKCS7::DETACHED if detached
    der = OpenSSL::PKCS7.sign(signer[:cert], signer[:key], content, [ signing_ca[:cert] ], flags).to_der
    base64 ? [ der ].pack("m") : der
  end

  # Appends a signature as an incremental update, like signing tools do.
  def pades(pdf, signer: signer_certificate, sub_filter: "ETSI.CAdES.detached")
    placeholder = "0" * 16_384
    update = +"\n9 0 obj\n<< /Type /Sig /Filter /Adobe.PPKLite /SubFilter /#{sub_filter} " \
              "/M (D:20270312101500+01'00') /ByteRange [0 0000000000 0000000000 0000000000] " \
              "/Contents <#{placeholder}> >>\nendobj\n%%EOF\n"
    doc = pdf.b + update.b
    b = doc.index("<#{placeholder}>")
    c = b + placeholder.size + 2
    byte_range = format("[0 %010d %010d %010d]", b, c, doc.bytesize - c)
    doc.sub!(%r{\[0 0000000000 0000000000 0000000000\]}, byte_range)

    signed_data = doc.byteslice(0, b) + doc.byteslice(c, doc.bytesize - c)
    der = OpenSSL::PKCS7.sign(signer[:cert], signer[:key], signed_data, [ signing_ca[:cert] ],
                              OpenSSL::PKCS7::BINARY | OpenSSL::PKCS7::DETACHED).to_der
    hex = der.unpack1("H*").ljust(placeholder.size, "0")
    doc.sub("<#{placeholder}>", "<#{hex}>")
  end

  def uploaded(bytes, filename:, content_type:)
    path = Rails.root.join("tmp", "#{SecureRandom.hex(6)}-#{filename}")
    File.binwrite(path, bytes)
    Rack::Test::UploadedFile.new(path, content_type, true)
  end

  private

  def build_cert(subject:, key:, issuer_key:, issuer: nil, not_before: 5.years.ago, not_after: 5.years.from_now)
    cert = OpenSSL::X509::Certificate.new
    cert.version = 2
    cert.serial = OpenSSL::BN.rand(64)
    cert.subject = OpenSSL::X509::Name.parse(subject)
    cert.issuer = issuer ? issuer.subject : cert.subject
    cert.public_key = key.public_key
    cert.not_before = not_before
    cert.not_after = not_after
    ef = OpenSSL::X509::ExtensionFactory.new
    ef.subject_certificate = cert
    ef.issuer_certificate = issuer || cert
    yield cert, ef if block_given?
    cert.sign(issuer_key, "SHA256")
    cert
  end
end

RSpec.configure { |config| config.include SigningHelpers }
